import React, { useEffect, useRef } from 'react';
import {
  Box,
  Chip,
  CircularProgress,
  Divider,
  IconButton,
  Paper,
  TextField,
  Tooltip,
  Typography,
  alpha,
} from '@mui/material';
import CloseIcon from '@mui/icons-material/Close';
import RefreshIcon from '@mui/icons-material/Refresh';
import SendIcon from '@mui/icons-material/Send';
import { AnimatePresence, motion } from 'framer-motion';
import { useChatData } from '../../hooks/useChatData';
import { ERROR_TYPE, SUGGESTED_PROMPTS, USER } from '../../constants/chatMessage';
import Markdown from './Markdown';

const TypingDots = () => (
  <Box sx={{ display: 'flex', gap: 0.6, alignItems: 'center', px: 0.5 }}>
    {[0, 1, 2].map((i) => (
      <Box
        key={i}
        component={motion.span}
        animate={{ opacity: [0.25, 1, 0.25] }}
        transition={{ duration: 1.1, repeat: Infinity, delay: i * 0.18 }}
        sx={{ width: 6, height: 6, borderRadius: '50%', bgcolor: 'primary.main' }}
      />
    ))}
  </Box>
);

const ChatBot = ({ open, setInitiateVini }) => {
  const {
    messages,
    input,
    setInput,
    chatResponse,
    loading,
    loadingMessage,
    warmUp,
    askSuggested,
    resetChat,
  } = useChatData();

  const scrollRef = useRef(null);
  const inputRef = useRef(null);

  // Follow the conversation as it streams in.
  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, loading]);

  // Wake the API and focus the composer as soon as the panel opens.
  useEffect(() => {
    if (!open) return;
    warmUp();
    const focus = setTimeout(() => inputRef.current?.focus(), 250);
    return () => clearTimeout(focus);
  }, [open, warmUp]);

  useEffect(() => {
    if (!open) return undefined;
    const onKeyDown = (e) => e.key === 'Escape' && setInitiateVini(false);
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [open, setInitiateVini]);

  const handleKeyDown = (e) => {
    // Enter sends; Shift+Enter inserts a newline.
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      chatResponse();
    }
  };

  const showSuggestions = messages.length <= 1 && !loading;

  return (
    <AnimatePresence>
      {open && (
        <Box
          component={motion.div}
          initial={{ opacity: 0, y: 24, scale: 0.97 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 24, scale: 0.97 }}
          transition={{ duration: 0.25, ease: 'easeOut' }}
          role="dialog"
          aria-modal="false"
          aria-label="Chat with Vini, Rushil's AI assistant"
          sx={{
            position: 'fixed',
            zIndex: 1300,
            // Full-screen sheet on phones, floating panel from tablet up.
            inset: { xs: 0, sm: 'auto 24px 24px auto' },
            width: { xs: '100%', sm: 420 },
            height: { xs: '100dvh', sm: 'min(620px, 78dvh)' },
            pb: { xs: 'env(safe-area-inset-bottom)', sm: 0 },
          }}
        >
          <Paper
            elevation={12}
            sx={{
              height: '100%',
              display: 'flex',
              flexDirection: 'column',
              bgcolor: 'background.paper',
              border: '1px solid',
              borderColor: (t) => alpha(t.palette.primary.main, 0.18),
              borderRadius: { xs: 0, sm: 3 },
              boxShadow: (t) => `0 0 40px ${alpha(t.palette.primary.main, 0.12)}`,
              overflow: 'hidden',
            }}
          >
            {/* Header */}
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, px: 2, py: 1.5 }}>
              <Box sx={{ flex: 1, minWidth: 0 }}>
                <Typography variant="subtitle1" sx={{ color: 'primary.light', fontWeight: 600, lineHeight: 1.2 }}>
                  Vini
                </Typography>
                <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                  Rushil&apos;s AI assistant
                </Typography>
              </Box>
              <Tooltip title="Start a new conversation">
                <IconButton size="small" onClick={resetChat} aria-label="Start a new conversation" sx={{ color: 'text.secondary' }}>
                  <RefreshIcon fontSize="small" />
                </IconButton>
              </Tooltip>
              <IconButton size="small" onClick={() => setInitiateVini(false)} aria-label="Close chat" sx={{ color: 'text.secondary' }}>
                <CloseIcon fontSize="small" />
              </IconButton>
            </Box>

            <Divider />

            {/* Messages */}
            <Box
              ref={scrollRef}
              role="log"
              aria-live="polite"
              aria-relevant="additions text"
              sx={{
                flex: 1,
                overflowY: 'auto',
                display: 'flex',
                flexDirection: 'column',
                gap: 1.25,
                px: 2,
                py: 2,
                scrollbarWidth: 'thin',
                '&::-webkit-scrollbar': { width: 5 },
                '&::-webkit-scrollbar-thumb': { bgcolor: 'divider', borderRadius: 3 },
              }}
            >
              {messages.map((msg, i) => {
                const isUser = msg.user_type === USER;
                const isError = msg.message_type === ERROR_TYPE;
                return (
                  <Box
                    key={i}
                    sx={{
                      alignSelf: isUser ? 'flex-end' : 'flex-start',
                      maxWidth: '88%',
                      px: 1.75,
                      py: 1.15,
                      borderRadius: 2,
                      fontSize: '0.9rem',
                      color: isError ? 'error.light' : 'text.primary',
                      bgcolor: (t) =>
                        isUser ? alpha(t.palette.primary.main, 0.12) : alpha(t.palette.common.white, 0.04),
                      border: '1px solid',
                      borderColor: (t) =>
                        isUser ? alpha(t.palette.primary.main, 0.22) : alpha(t.palette.common.white, 0.06),
                    }}
                  >
                    <Markdown>{msg.message_text}</Markdown>
                  </Box>
                );
              })}

              {loading && (
                <Box sx={{ alignSelf: 'flex-start', display: 'flex', flexDirection: 'column', gap: 0.75 }}>
                  <Box
                    sx={{
                      px: 1.75,
                      py: 1.15,
                      borderRadius: 2,
                      bgcolor: (t) => alpha(t.palette.common.white, 0.04),
                      border: '1px solid',
                      borderColor: (t) => alpha(t.palette.common.white, 0.06),
                    }}
                  >
                    <TypingDots />
                  </Box>
                  {loadingMessage && (
                    <Typography variant="caption" sx={{ color: 'text.secondary', px: 0.5 }}>
                      {loadingMessage}
                    </Typography>
                  )}
                </Box>
              )}

              {showSuggestions && (
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.75, mt: 0.5 }}>
                  {SUGGESTED_PROMPTS.map((prompt) => (
                    <Chip
                      key={prompt}
                      label={prompt}
                      size="small"
                      clickable
                      onClick={() => {
                        askSuggested(prompt);
                        inputRef.current?.focus();
                      }}
                      sx={{
                        color: 'text.secondary',
                        borderColor: 'divider',
                        bgcolor: 'transparent',
                        border: '1px solid',
                        '&:hover': {
                          color: 'primary.main',
                          borderColor: (t) => alpha(t.palette.primary.main, 0.5),
                          bgcolor: (t) => alpha(t.palette.primary.main, 0.06),
                        },
                      }}
                    />
                  ))}
                </Box>
              )}
            </Box>

            <Divider />

            {/* Composer */}
            <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: 1, p: 1.5 }}>
              <TextField
                inputRef={inputRef}
                fullWidth
                multiline
                maxRows={4}
                size="small"
                placeholder="Ask about his experience…"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyDown}
                inputProps={{ 'aria-label': 'Ask Vini a question' }}
                sx={{
                  '& .MuiOutlinedInput-root': {
                    fontSize: '0.9rem',
                    '& fieldset': { borderColor: 'divider' },
                    '&:hover fieldset': { borderColor: (t) => alpha(t.palette.primary.main, 0.35) },
                    '&.Mui-focused fieldset': { borderColor: 'primary.main' },
                  },
                }}
              />
              <IconButton
                onClick={chatResponse}
                disabled={loading || !input.trim()}
                aria-label="Send message"
                sx={{ color: 'primary.main', '&.Mui-disabled': { color: 'divider' } }}
              >
                {loading ? <CircularProgress size={18} sx={{ color: 'primary.main' }} /> : <SendIcon />}
              </IconButton>
            </Box>
          </Paper>
        </Box>
      )}
    </AnimatePresence>
  );
};

export default ChatBot;
