import { useCallback, useEffect, useRef, useState } from 'react';
import { v4 as uuidv4 } from 'uuid';
import {
  BOT,
  ERROR_TYPE,
  GENERIC_ERROR_MESSAGE,
  RATE_LIMIT_MESSAGE,
  SESSION_KEY,
  TRANSCRIPT_KEY,
  USER,
  VINI_OPENING_MESSAGE,
  WAKING_UP_MESSAGE,
} from '../constants/chatMessage';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL;
const AUTH_TOKEN = process.env.REACT_APP_BACKEND_AUTHENTICATION_TOKEN;

// The API sleeps when idle and can take the better part of a minute to wake, so the ceiling is
// generous. The "waking up" hint appears long before this.
const REQUEST_TIMEOUT_MS = 90000;
const WAKING_UP_AFTER_MS = 4000;

const authHeaders = () => ({
  'Content-Type': 'application/json',
  Authorization: `Bearer ${AUTH_TOKEN}`,
});

const greeting = () => ({ user_type: BOT, message_text: VINI_OPENING_MESSAGE });

const readSession = () => {
  try {
    return localStorage.getItem(SESSION_KEY);
  } catch {
    return null;
  }
};

/** Restore a previous conversation so reopening the panel is instant and survives a reload. */
const readTranscript = () => {
  try {
    const raw = localStorage.getItem(TRANSCRIPT_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    return Array.isArray(parsed) && parsed.length > 0 ? parsed : [greeting()];
  } catch {
    return [greeting()];
  }
};

export const useChatData = () => {
  const [messages, setMessages] = useState(readTranscript);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');

  const sessionIdRef = useRef(null);
  const abortRef = useRef(null);
  const warmedRef = useRef(false);

  // Persist the transcript so closing the panel (or the tab) doesn't lose the conversation.
  useEffect(() => {
    try {
      localStorage.setItem(TRANSCRIPT_KEY, JSON.stringify(messages));
    } catch {
      /* storage unavailable (private mode, quota) — the chat still works in memory */
    }
  }, [messages]);

  // Abort any in-flight stream when the consumer unmounts.
  useEffect(() => () => abortRef.current?.abort(), []);

  const getSessionId = useCallback(() => {
    if (sessionIdRef.current) return sessionIdRef.current;
    let id = readSession();
    if (!id) {
      id = uuidv4();
      try {
        localStorage.setItem(SESSION_KEY, id);
      } catch {
        /* fall back to an in-memory session id */
      }
    }
    sessionIdRef.current = id;
    return id;
  }, []);

  /**
   * Ping the API so it starts waking while the visitor is still typing. Fire-and-forget: a
   * failure here is not worth surfacing, the real request will report any problem.
   */
  const warmUp = useCallback(() => {
    if (warmedRef.current || !BACKEND_URL) return;
    warmedRef.current = true;
    fetch(`${BACKEND_URL}/test`, { headers: authHeaders() }).catch(() => {});
  }, []);

  const appendBotError = useCallback((text) => {
    setMessages((prev) => [...prev, { user_type: BOT, message_type: ERROR_TYPE, message_text: text }]);
  }, []);

  const chatResponse = useCallback(async () => {
    const question = input.trim();
    // One request at a time: concurrent streams would interleave into the same bubble.
    if (!question || loading) return;

    const sessionId = getSessionId();
    const controller = new AbortController();
    abortRef.current = controller;
    const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
    const wakingHint = setTimeout(() => setLoadingMessage(WAKING_UP_MESSAGE), WAKING_UP_AFTER_MS);

    setInput('');
    setLoading(true);
    setLoadingMessage('');
    setMessages((prev) => [...prev, { user_type: USER, message_text: question }]);

    // Index of the assistant bubble that streaming tokens accumulate into.
    let botIndex = -1;
    const appendToken = (token) => {
      setMessages((prev) => {
        const next = [...prev];
        if (botIndex === -1) {
          botIndex = next.length;
          next.push({ user_type: BOT, message_text: token });
        } else {
          next[botIndex] = { ...next[botIndex], message_text: next[botIndex].message_text + token };
        }
        return next;
      });
      // The first token means the server is answering — drop the "waking up" hint.
      clearTimeout(wakingHint);
      setLoadingMessage('');
    };

    try {
      const response = await fetch(`${BACKEND_URL}/chat/stream`, {
        method: 'POST',
        headers: authHeaders(),
        body: JSON.stringify({ message_text: question, session_id: sessionId, user_type: USER }),
        signal: controller.signal,
      });

      if (!response.ok) {
        appendBotError(response.status === 429 ? RATE_LIMIT_MESSAGE : GENERIC_ERROR_MESSAGE);
        return;
      }

      const reader = response.body?.getReader();
      if (!reader) {
        appendBotError(GENERIC_ERROR_MESSAGE);
        return;
      }

      const decoder = new TextDecoder();
      let buffer = '';
      let streamError = null;

      // SSE frames are separated by a blank line, and a frame can straddle two chunks, so the
      // tail of the buffer is kept until its terminator arrives.
      // eslint-disable-next-line no-constant-condition
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const frames = buffer.split('\n\n');
        buffer = frames.pop() ?? '';

        for (const frame of frames) {
          const line = frame.trim();
          if (!line.startsWith('data:')) continue;

          const payload = line.slice(5).trim();
          if (payload === '[DONE]') continue;

          try {
            const parsed = JSON.parse(payload);
            if (parsed.token) appendToken(parsed.token);
            else if (parsed.error) streamError = parsed.error;
          } catch {
            /* ignore keep-alives and partial frames */
          }
        }
      }

      // Only surface a stream error if nothing usable was rendered.
      if (streamError && botIndex === -1) appendBotError(GENERIC_ERROR_MESSAGE);
    } catch (error) {
      if (error.name !== 'AbortError') appendBotError(GENERIC_ERROR_MESSAGE);
    } finally {
      clearTimeout(timeout);
      clearTimeout(wakingHint);
      abortRef.current = null;
      setLoading(false);
      setLoadingMessage('');
    }
  }, [input, loading, getSessionId, appendBotError]);

  const askSuggested = useCallback((question) => setInput(question), []);

  const resetChat = useCallback(() => {
    abortRef.current?.abort();
    sessionIdRef.current = uuidv4();
    try {
      localStorage.setItem(SESSION_KEY, sessionIdRef.current);
      localStorage.removeItem(TRANSCRIPT_KEY);
    } catch {
      /* nothing to clean up */
    }
    setMessages([greeting()]);
    setInput('');
    setLoading(false);
    setLoadingMessage('');
  }, []);

  return {
    messages,
    input,
    setInput,
    chatResponse,
    loading,
    loadingMessage,
    warmUp,
    askSuggested,
    resetChat,
  };
};
