import React from 'react';
import { Fab, Tooltip, alpha } from '@mui/material';
import ChatBubbleOutlineIcon from '@mui/icons-material/ChatBubbleOutline';
import { AnimatePresence, motion } from 'framer-motion';

/**
 * Persistent entry point to the chat.
 *
 * The hero's "Ask Vini" button is only reachable at the top of the page, so this keeps Vini one
 * click away while a visitor is reading the experience and projects sections. It hides itself
 * while the panel is open.
 */
const Launcher = ({ open, onOpen }) => (
  <AnimatePresence>
    {!open && (
      <Tooltip title="Ask Vini about Rushil" placement="left">
        <Fab
          component={motion.button}
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: 0.8 }}
          transition={{ duration: 0.2 }}
          color="primary"
          onClick={onOpen}
          aria-label="Ask Vini about Rushil"
          sx={{
            position: 'fixed',
            bottom: { xs: 20, sm: 24 },
            right: { xs: 20, sm: 24 },
            zIndex: 1200,
            boxShadow: (t) => `0 0 26px ${alpha(t.palette.primary.main, 0.45)}`,
          }}
        >
          <ChatBubbleOutlineIcon />
        </Fab>
      </Tooltip>
    )}
  </AnimatePresence>
);

export default Launcher;
