import React, { useState } from 'react';
import { ThemeProvider } from '@mui/material/styles';
import { CssBaseline, Box } from '@mui/material';
import theme from './theme';
import IntroductionV2 from './components/IntroductionV2';
import Experience from './components/Experience';
import Skills from './components/Skills';
import Education from './components/Education';
import Chat from './components/Chat';
import ChatLauncher from './components/Chat/Launcher';
import Project from './components/Projects';
import Navbar from './components/Navbar';

function App() {
  const [initiateVini, setInitiateVini] = useState(false);
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box>
        <Navbar />
        <Box id="intro">
          <IntroductionV2 setInitiateVini={setInitiateVini} initiateVini={initiateVini} />
        </Box>
        <Box id="experience">
          <Experience />
        </Box>
        <Box id="projects">
          <Project />
        </Box>
        <Box id="skills">
          <Skills />
        </Box>
        <Box id="education">
          <Education />
        </Box>
        {/* Kept mounted so closing the panel preserves the conversation instead of tearing it down. */}
        <Chat open={initiateVini} setInitiateVini={setInitiateVini} />
        <ChatLauncher open={initiateVini} onOpen={() => setInitiateVini(true)} />
      </Box>
    </ThemeProvider>
  );
}

export default App;
