import React from 'react';
import { Box, Chip, Container, Grid, Paper, Typography, alpha } from '@mui/material';
import SchoolOutlinedIcon from '@mui/icons-material/SchoolOutlined';
import { motion } from 'framer-motion';
import { educationDetails } from './utils/educationDetails';
import SectionHeader from '../SectionHeader';

const Education = () => (
  <Box sx={{ py: 12 }}>
    <Container maxWidth="lg">
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true }}
        transition={{ duration: 0.6 }}
      >
        <SectionHeader title="Education" />
      </motion.div>

      <Grid container spacing={3} justifyContent="center">
        {educationDetails.map(({ degree, school, location, duration, gpa, coursework }, index) => (
          <Grid item xs={12} md={6} key={degree}>
            <Paper
              component={motion.div}
              initial={{ opacity: 0, y: 24 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: index * 0.1 }}
              elevation={0}
              sx={{
                height: '100%',
                p: 3.5,
                borderRadius: 3,
                bgcolor: 'background.paper',
                border: '1px solid',
                borderColor: (t) => alpha(t.palette.primary.main, 0.12),
                boxShadow: (t) => `0 0 24px ${alpha(t.palette.primary.main, 0.06)}`,
              }}
            >
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.25, mb: 1.5 }}>
                <SchoolOutlinedIcon sx={{ color: 'primary.main' }} />
                <Typography variant="h6" sx={{ color: 'text.primary', fontWeight: 600, fontSize: '1.05rem' }}>
                  {school}
                </Typography>
              </Box>

              <Typography variant="body2" sx={{ color: 'primary.light', mb: 0.75 }}>
                {degree}
              </Typography>

              <Typography variant="caption" sx={{ color: 'text.secondary', display: 'block', mb: 2 }}>
                {location} · {duration} · GPA {gpa}
              </Typography>

              {coursework.length > 0 && (
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.75 }}>
                  {coursework.map((course) => (
                    <Chip
                      key={course}
                      label={course}
                      size="small"
                      sx={{
                        bgcolor: (t) => alpha(t.palette.primary.main, 0.08),
                        color: 'text.secondary',
                        border: '1px solid',
                        borderColor: (t) => alpha(t.palette.primary.main, 0.16),
                        fontSize: '0.75rem',
                      }}
                    />
                  ))}
                </Box>
              )}
            </Paper>
          </Grid>
        ))}
      </Grid>
    </Container>
  </Box>
);

export default Education;
