import React from 'react';
import { Box, Link, Typography } from '@mui/material';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

/**
 * Renders assistant markdown inside a chat bubble.
 *
 * The bot is prompted to answer in short markdown, so bullets, bold and links all need to render
 * rather than showing up as literal asterisks. Spacing is tightened well below document defaults
 * because these are chat bubbles, not article bodies.
 */
const components = {
  p: ({ children }) => (
    <Typography component="p" sx={{ fontSize: 'inherit', lineHeight: 1.65, m: 0, '& + p': { mt: 1 } }}>
      {children}
    </Typography>
  ),
  ul: ({ children }) => (
    <Box component="ul" sx={{ pl: 2.25, my: 0.75, '& + p': { mt: 1 } }}>
      {children}
    </Box>
  ),
  ol: ({ children }) => (
    <Box component="ol" sx={{ pl: 2.25, my: 0.75 }}>
      {children}
    </Box>
  ),
  li: ({ children }) => (
    <Box component="li" sx={{ fontSize: 'inherit', lineHeight: 1.6, mb: 0.5, '&::marker': { color: 'primary.main' } }}>
      {children}
    </Box>
  ),
  a: ({ href, children }) => (
    <Link
      href={href}
      target="_blank"
      rel="noopener noreferrer"
      sx={{ color: 'primary.light', textDecorationColor: 'currentColor', overflowWrap: 'anywhere' }}
    >
      {children}
    </Link>
  ),
  strong: ({ children }) => (
    <Box component="strong" sx={{ fontWeight: 600, color: 'text.primary' }}>
      {children}
    </Box>
  ),
  code: ({ children }) => (
    <Box
      component="code"
      sx={{
        fontFamily: 'monospace',
        fontSize: '0.85em',
        px: 0.6,
        py: 0.15,
        borderRadius: 0.75,
        bgcolor: 'rgba(255, 255, 255, 0.08)',
        overflowWrap: 'anywhere',
      }}
    >
      {children}
    </Box>
  ),
  pre: ({ children }) => (
    <Box component="pre" sx={{ my: 0.75, p: 1, borderRadius: 1, bgcolor: 'rgba(0, 0, 0, 0.35)', overflowX: 'auto' }}>
      {children}
    </Box>
  ),
  // Headings would be oversized in a bubble; render them as emphasised text instead.
  h1: ({ children }) => <Box sx={{ fontWeight: 600, mt: 1 }}>{children}</Box>,
  h2: ({ children }) => <Box sx={{ fontWeight: 600, mt: 1 }}>{children}</Box>,
  h3: ({ children }) => <Box sx={{ fontWeight: 600, mt: 1 }}>{children}</Box>,
};

const Markdown = ({ children }) => (
  <ReactMarkdown remarkPlugins={[remarkGfm]} components={components}>
    {children || ''}
  </ReactMarkdown>
);

export default Markdown;
